.version 7.1
.target sm_80
.address_size 64

.visible .entry tanh_kernel(
    .param .u64 in_ptr,
    .param .u64 out_ptr,
    .param .u64 n
)
{
    .reg .pred   %p;
    .reg .u32    %tid_x, %ctaid_x, %ntid_x, %grid_x, %tmp32;
    .reg .u64    %idx, %stride, %n64;
    .reg .u64    %in_ptr64, %out_ptr64;
    .reg .u64    %addr;
    .reg .u16    %x_half_raw, %y_half_raw;
    .reg .f16    %x_half, %y_half;
    .reg .f32    %x_f32, %y_f32;

    // -----------------------------------------------------------------
    // load kernel arguments
    // -----------------------------------------------------------------
    ld.param.u64    %in_ptr64, [in_ptr];
    ld.param.u64    %out_ptr64, [out_ptr];
    ld.param.u64    %n64,      [n];

    // -----------------------------------------------------------------
    // thread identifiers
    // -----------------------------------------------------------------
    mov.u32 %tid_x,    %tid.x;
    mov.u32 %ctaid_x,  %ctaid.x;
    mov.u32 %ntid_x,   %ntid.x;
    mov.u32 %grid_x,   %nctaid.x;               // gridDim.x

    // linear thread id   idx = blockIdx.x * blockDim.x + threadIdx.x
    mul.lo.u32 %tmp32, %ctaid_x, %ntid_x;
    add.u32    %tmp32, %tmp32, %tid_x;
    cvt.u64.u32 %idx, %tmp32;

    // total number of threads = gridDim.x * blockDim.x
    mul.lo.u32 %tmp32, %grid_x, %ntid_x;
    cvt.u64.u32 %stride, %tmp32;

    // -----------------------------------------------------------------
    // main loop: each thread processes strided elements
    // -----------------------------------------------------------------
LOOP:
    setp.ge.u64 %p, %idx, %n64;
    @%p bra END;

    // byte address = idx * sizeof(half)  (sizeof(half)=2)
    shl.b64 %addr, %idx, 1;                 // addr = idx << 1

    // load half (fp16) from input
    add.u64 %addr, %in_ptr64, %addr;
    ld.global.u16 %x_half_raw, [%addr];
    mov.b16 %x_half, %x_half_raw;

    // convert to fp32, compute tanh, convert back to fp16
    cvt.rn.f32.f16 %x_f32, %x_half;
    tanh.approx.f32 %y_f32, %x_f32;
    cvt.rn.f16.f32 %y_half, %y_f32;
    mov.b16 %y_half_raw, %y_half;

    // store result
    add.u64 %addr, %out_ptr64, %addr;
    st.global.u16 [%addr], %y_half_raw;

    // advance to next element handled by this thread
    add.u64 %idx, %idx, %stride;
    bra LOOP;

END:
    ret;
}
"""

